vector<int> computeLPS(string pat) {
    int m = pat.length();
    vector<int> lps(m, 0);
    int len = 0, i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) { lps[i] = len + 1; len++; i++; }
        else { if (len != 0) { len = lps[len - 1]; } else { lps[i] = 0; i++; } }
    }
    return lps;
}
void KMPSearch(string pat, string txt) {
    int n = txt.length(), m = pat.length();
    vector<int> lps = computeLPS(pat);
    int i = 0, j = 0;
    while (i < n) {
        if (pat[j] == txt[i]) { j++; i++; }
        if (j == m) { /* Match found at i-j */ j = lps[j - 1]; }
        else if (i < n && pat[j] != txt[i]) {
            if (j != 0) j = lps[j - 1]; else i++;
        }
    }
}

void RabinKarp(string pat, string txt) {
    int M = pat.length(), N = txt.length();
    int i, j, p = 0, t = 0, h = 1, d = 256, q = 101; // Prime
    for (i = 0; i < M - 1; i++) h = (h * d) % q;
    for (i = 0; i < M; i++) {
        p = (d * p + pat[i]) % q;
        t = (d * t + txt[i]) % q;
    }
    for (i = 0; i <= N - M; i++) {
        if (p == t) {
            for (j = 0; j < M; j++) if (txt[i+j] != pat[j]) break;
            if (j == M) cout << "Pattern found at " << i << endl;
        }
        if (i < N - M) {
            t = (d * (t - txt[i] * h) + txt[i + M]) % q;
            if (t < 0) t = (t + q);
        }
    }
}

vector<int> nextGreaterElement(vector<int>& nums) {
    int n = nums.size();
    vector<int> res(n, -1);
    stack<int> s;
    for (int i = 0; i < n; i++) {
        while (!s.empty() && nums[s.top()] < nums[i]) {
            res[s.top()] = nums[i];
            s.pop();
        }
        s.push(i);
    }
    return res;
}

int maxOverlap(vector<vector<int>>& intervals) {
    map<int, int> events;
    for (auto& interval : intervals) {
        events[interval[0]]++;
        events[interval[1]]--;
    }
    int active = 0, max_overlap = 0;
    for (auto& event : events) {
        active += event.second;
        max_overlap = max(max_overlap, active);
    }
    return max_overlap;
}
